mapper.codeEditorJavascript:
const MONTHS=['ינואר','פברואר','מרץ','אפריל','מאי','יוני','יולי','אוגוסט','ספטמבר','אוקטובר','נובמבר','דצמבר'];
const arr=v=>{ if(typeof v==='string'){ try{return JSON.parse(v);}catch(e){return [];} } return Array.isArray(v)?v:[]; };
const titles=arr(input.sheets).map(s=>String(((s||{}).properties||{}).title||'').trim());
const nowIL=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Jerusalem'}));
const tabs=[];
for(const off of [0,-1,1]){ const d=new Date(nowIL.getFullYear(),nowIL.getMonth()+off,1); const t=MONTHS[d.getMonth()]+' '+d.getFullYear(); if(titles.includes(t)) tabs.push(t); }
const q=s=>"'"+s+"'";
const filters=tabs.length? tabs.map(t=>({a1Range:q(t)+'!A1:H2000'})) : [{a1Range:q('הגדרות')+'!A1:A1'}];
return {readBody: JSON.stringify({dataFilters:filters, valueRenderOption:'FORMATTED_VALUE'})};

const digits=s=>String(s==null?'':s).replace(/\D/g,'');
const norm=s=>String(s==null?'':s).replace(/\s+/g,' ').trim();
const arr=v=>{ if(typeof v==='string'){ try{return JSON.parse(v);}catch(e){return [];} } return Array.isArray(v)?v:[]; };
const cf={}; for(const f of arr(input.cf)){ if(f && f.name) cf[f.name]=f.value; }
const tags=arr(input.tags).map(t=>norm((t&&t.name)||t));
const gotFollowup=tags.includes('קיבל פולואפ');
const mcRep=norm(cf['שם נציג']);
// RULE (15/11/2026): full rep name is kept only in the Followup data store (repFull), never in a ManyChat field the customer can see. Priority: דוח מכר > repFull > ManyChat 'שם נציג' (first name only). Do not remove.
const repFull=norm(input.repFull);
const rawDate=norm(cf['תאריך ושעת שיחה']);
let text=norm(input.text); if(!text || text.includes('{{')) text=norm(input.text2);
text=text.slice(0,500);
// RULE (Steve 15/11/2026): a reply that is only a high rating (4 or 5, e.g. "5", "5/5", "5 🙏") is not sent to the rep. Low ratings and any real text still go. Do not remove.
const highOnly=/^[45]\s*(?:\/\s*5|מתוך\s*5)?(?:\s|[!.,]|🙏|👍|❤️|😊)*$/.test(text);
let phone=digits(input.wa); if(!phone) phone=digits(cf['WA ID']||input.ph);
const custPhone=phone.length>=9?('0'+phone.slice(-9)):phone;
const name=norm(input.name)||'לא ידוע';
// תאריך השיחה שנקבע בפולואפ – מציגים בשעון ישראל; לקוח שהשיחה שלו לפני יותר מ-14 יום כבר לא נחשב תשובה לפולואפ
let dateStr='', old=false;
if(rawDate){ const d=new Date(rawDate); if(!isNaN(d)){ dateStr=d.toLocaleString('he-IL',{timeZone:'Asia/Jerusalem',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}); old=(Date.now()-d.getTime())/86400000>14; } else dateStr=rawDate; }
// RULE (Steve 12/11/2026): the followup reply goes to the selling rep in the דוח מכר (current/previous/next month) when the customer's phone is there; the ManyChat 'שם נציג' field is only a fallback (it gets overwritten). A phone listed for 2+ different customers -> Steve + Yarden, not a guess. Do not remove.
const k9=phone.slice(-9); const names={};
if(k9.length===9){ for(const vr of arr(input.sales)){ const vals=((vr&&vr.valueRange)||vr||{}).values||[]; for(const r of vals.slice(1)){ if(r&&digits(r[3]).slice(-9)===k9){ const n=norm(r[2]); if(n) names[n]=norm(r[7]); } } } }
const nk=Object.keys(names); const dup=nk.length>1;
// RULE (Yarden 16/11/2026): a customer who got the 'עסקה נסגרה' message (Railway sets only ManyChat 'שם נציג', no tag) is handled like a followup reply: דוח מכר first, then the rep name. If the rep is not ours -> WhatsApp group 'טו צ׳אט' (no 48h limit). Our customer -> nothing is sent. A followup older than 14 days falls back to this path. Do not remove.
const isFollow=gotFollowup&&!old;
let tc={}; try{ tc=typeof input.tc==='string'?JSON.parse(input.tc||'{}'):(input.tc||{}); }catch(e){ tc={}; }
const tcClosed=(tc.inactiveCampaigns||[]).filter(c=>c&&String(c.reason||'').toUpperCase()==='CLOSED'&&norm(c.agentName)).sort((a,b)=>String(b.timestamp||'').localeCompare(String(a.timestamp||'')));
const tcCloser=tcClosed.length?norm(tcClosed[0].agentName):'';
const tcFollow=(tc.activeLeads||[]).map(l=>norm(l&&l.followByName)).filter(Boolean);
const isClosed=!isFollow&&!!mcRep;
const mcFirst=mcRep.split(' ')[0];
const tcFollowMatch=mcFirst?(tcFollow.find(n=>n.split(' ')[0]===mcFirst)||''):'';
const rep=norm((nk.length===1&&names[nk[0]])?names[nk[0]]:(isFollow?(tcFollowMatch||repFull||mcRep):(tcCloser||mcRep)));
const showName=nk.length===1?nk[0]:name;
// RULE (Yarden 16/11/2026): ownership is decided by the rep's FULL name, because Liran's/Yossi's team also has first names like ours (e.g. 'דניאל דמוזה' is NOT ours). Full name sources: דוח מכר -> ToChat (agentName of the latest CLOSED deal / followByName of an open followup) -> Followup data store repFull -> ManyChat first name (fallback only). A full name matches our rep only if it equals a name in יעדים, or יעדים has a single-word entry with that first name and NO full-name entry with the same first name. If ANY known full name is ours, the customer is ours and never goes to the group. Do not remove.
const rows=arr(input.targets).filter(r=>r&&r[0]&&r[1]).map(r=>({n:norm(r[0]),p:digits(r[1])}));
const toIntl=p=>{ p=String(p||''); if(p.startsWith('0')) p='972'+p.slice(1); return /^9725\d{8}$/.test(p)?p:''; };
const lookup=(nm)=>{ nm=norm(nm); if(!nm) return {hit:null,amb:[]};
  const ex=rows.find(r=>r.n===nm); if(ex) return {hit:ex,amb:[]};
  const first=nm.split(' ')[0]; const same=rows.filter(r=>r.n.split(' ')[0]===first);
  if(nm.includes(' ')){ const fulls=same.filter(r=>r.n.includes(' ')); const singles=same.filter(r=>!r.n.includes(' ')); return {hit:(fulls.length===0&&singles.length===1)?singles[0]:null,amb:[]}; }
  if(same.length===1) return {hit:same[0],amb:[]};
  if(same.length>1) return {hit:null,amb:same.map(r=>r.n)};
  const sw=rows.filter(r=>r.n.startsWith(nm)||nm.startsWith(r.n)); return {hit:sw.length===1?sw[0]:null,amb:[]};
};
const isOur=nm=>{ const l=lookup(nm); return !!(l.hit&&toIntl(l.hit.p)); };
let repPhone=''; let amb=[];
if(rep){ const l=lookup(rep); amb=l.amb; if(l.hit) repPhone=toIntl(l.hit.p); }
const fullKnown=[...nk.map(n=>names[n]), tcCloser, ...tcFollow, repFull].map(norm).filter(Boolean);
const oursByAny=fullKnown.some(isOur);
let reason='';
if(!isFollow&&!isClosed) reason=gotFollowup?'followup older than 14 days, no rep name':'no followup tag and no rep name';
else if(!text) reason='no text';
else if(highOnly) reason='high rating only (4/5) - not sent';
else if(!rep) reason='no rep name';
else if(!repPhone) reason='rep phone not found: '+rep;
else if(isClosed) reason='closed deal - our rep ('+rep+') - not sent';
const send=isFollow&&!dup&&reason==='';
// RULE (Steve 16/11/2026): the דוח מכר is always checked first by the customer's phone. If the phone is not there and the rep name matches 2+ of OUR reps (e.g. 'דניאל' = דניאל אלימלך / דניאל קראוז), the reply goes to the WhatsApp group 'טו צ׳אט' (not Steve+Yarden). Do not remove.
// RULE (Yarden 16/11/2026): replaces the 48h part of the rule below - a followup reply of a rep that is not ours ALWAYS goes to the WhatsApp group 'טו צ׳אט', with no time limit (no more 'over 48h -> Steve + Yarden'). Do not remove.
// (old) RULE (Steve/Yarden 15/11/2026): any rep we don't recognize (no rep name, or a name with no phone in יעדים) is one of Liran's/Yossi's reps. If the customer replied within 48h of the followup being sent (data store sentAt) -> send to the WhatsApp group 'טו צ׳אט' (120363429258204378@g.us), without saying 'not recognized'. Over 48h -> Steve + Yarden in private. No sentAt -> group. Do not remove.
const base=!dup&&(isFollow||isClosed)&&!!text&&!highOnly&&!repPhone;
const ourAmb=amb.length>1;
const sentMs=Date.parse(norm(input.sentAt));
const hrs=isNaN(sentMs)?null:(Date.now()-sentMs)/3600000;
// RULE (Yarden 16/11/2026): if the יעדים sheet could not be read (no reps loaded), every rep looks 'not ours' - never send to the group then; alert Steve + Yarden instead. Do not remove.
const targetsOk=rows.length>0;
// RULE (Yardiv 16/11/2026): a customer who got a followup MORE than 14 days ago and writes again ('לקוח חזר לכתוב') is NOT sent to the WhatsApp group 'טו צ׳אט' - nothing is sent for him. Do not remove.
const oldFollowBack=isClosed&&gotFollowup;
const toGroup=base&&!oursByAny&&targetsOk&&!oldFollowBack;
const lateOther=false;
const repMissing=base&&(oursByAny||!targetsOk);
const sendMgr=(dup&&(isFollow||isClosed)&&!!text&&!highOnly)||repMissing||lateOther;
const details='שם הלקוח: '+showName+'\nנייד: '+custPhone+(dateStr&&isFollow?'\nשיחה שנקבעה: '+dateStr:'')+'\nמה הלקוח כתב: "'+text+'"';
const msg='📩 לקוח ענה להודעת הפולואפ שלך\n\n'+details+'\n\n⚠️ אי אפשר להגיב כאן – תשובה להודעה הזאת לא מגיעה ללקוח. חובה לשלוח ללקוח הודעה מהוואטסאפ הפרטי או להתקשר אליו.';
const groupMsg=(isClosed?(gotFollowup?'📩 לקוח חזר לכתוב (קיבל פולואפ לפני יותר מ-14 יום)':'📩 לקוח ענה להודעת "עסקה נסגרה"'):'📩 לקוח ענה להודעת הפולואפ')+(rep?' (נציג: '+rep+')':'')+'\n\n'+details;
const lateMsg='📩 לקוח של הנציגים של לירן/יוסי ענה לפולואפ אחרי יותר מ-48 שעות'+(rep?' (נציג: '+rep+')':'')+'\n\n'+details;
const dupMsg='⚠️ מספר כפול בדוח מכר – לקוח ענה לפולואפ ולא העברתי לנציג, כי לא ברור של מי הלקוח\nהנייד '+custPhone+' רשום על:\n'+nk.map(n=>n+' – '+(names[n]||'בלי נציג')).join('\n')+'\nמה הלקוח כתב: "'+text+'"\n\nצריך לבדוק מי הלקוח, להעביר לנציג שלו ולתקן את הנייד בדוח.';
const missMsg=!targetsOk?('⚠️ לקוח ענה ולא העברתי – לא הצלחתי לקרוא את גיליון יעדים, אז אין לי איך לדעת אם הנציג "'+rep+'" שלנו\n\n'+details+'\n\nצריך לבדוק ולהעביר ידנית.'):oursByAny?('⚠️ לקוח ענה ולא העברתי – הנציג "'+rep+'" לא נמצא ביעדים, אבל הלקוח רשום גם אצל נציג שלנו ('+fullKnown.filter(isOur).join(', ')+')\n\n'+details+'\n\nצריך להעביר לנציג הנכון.'):('⚠️ לקוח ענה לפולואפ ולא העברתי לנציג – השם "'+rep+'" מתאים לכמה נציגים ('+amb.join(', ')+')\n\n'+details+'\n\nצריך להעביר לנציג הנכון ולתקן את שם הנציג (שם מלא) בפולואפ.');
return {send, sendMgr, toGroup, reason, source:isClosed?'closed':(isFollow?'followup':'none'), rep, repPhone, hrs, msg, groupMsg, mgrMsg: dup?dupMsg:(lateOther?lateMsg:missMsg), dup, mgr1:'972544604246', mgr2:'972504445169', groupId:'120363429258204378@g.us'};
